            "harga_satuan": d.get("harga") or 0,
            "subtotal": d.get("subtotal_rp") or 0,
            "stock_ledger_id": None,
        })

    if skipped:
        print(f"  [detail] {skipped} baris detail dilewati (tidak ada pos_transaction/items).")
    return result

