const delay = (ms = 200): Promise<void> => new Promise(resolve => setTimeout(resolve, ms));

// ─── Types ───────────────────────────────────────────────────────────────────

export type StatusRetur = 'tercatat' | 'batal';

export type MetodePembayaran = 'tunai' | 'transfer' | 'debit' | 'qris';

export const METODE_PEMBAYARAN_LABEL: Record<MetodePembayaran, string> = {
  tunai: 'Tunai',
  transfer: 'Transfer Bank',
  debit: 'Kartu Debit',
  qris: 'QRIS',
};

export function normalizeMetodePembayaran(value: unknown): MetodePembayaran {
  return value === 'transfer' || value === 'debit' || value === 'qris' ? value : 'tunai';
}

export const STATUS_LABEL: Record<StatusRetur, string> = {
  tercatat: 'Tercatat',
  batal: 'Dibatalkan',
};

export const STATUS_BADGE: Record<StatusRetur, { bg: string; text: string }> = {
  tercatat: { bg: '#DCFCE7', text: '#166534' },
  batal: { bg: '#FEE2E2', text: '#991B1B' },
};

