function mapApiRetur(item: any): ReturPenjualanItem {
  const details = item.details ?? item.detail ?? [];
  return {
    id: Number(item.id),
    no_retur: item.no_retur,
    tanggal: item.tanggal,
    pelanggan_id: Number(item.customer_id ?? item.customer?.id ?? 0),
    pelanggan_nama: item.customer_nama ?? item.customer?.nama ?? '-',
    pelanggan_kode: item.customer_kode ?? item.customer?.kode ?? '',
    faktur_penjualan_id: Number(details[0]?.pos_transaction_id ?? 0),
    faktur_no: Array.from(new Set(details.map((d: any) => d.pos_transaction?.invoice_number ?? d.invoice_number).filter(Boolean))).join(', '),
    keterangan: item.keterangan ?? null,
    metode_pembayaran: normalizeMetodePembayaran(item.metode_pengembalian ?? item.metode_pembayaran),
    jumlah_pengembalian: Number(item.jumlah_pengembalian ?? 0),
    status: item.status === 'cancelled' || item.status === 'batal' ? 'batal' : 'tercatat',
    dibuat_oleh: item.kasir?.name ?? item.created_by_name ?? '',
    diubah_oleh: item.updated_by_name ?? null,
    created_at: item.created_at ?? item.tanggal,
    updated_at: item.updated_at ?? item.created_at ?? item.tanggal,
    detail: details.map((d: any) => ({
      id: Number(d.id),
      faktur_penjualan_detail_id: Number(d.pos_transaction_item_id ?? d.id),
      produk_id: Number(d.produk_id ?? d.product_id ?? d.pos_transaction_item?.product_id ?? d.produk?.id),
      kode_produk: d.produk_kode ?? d.product_code ?? d.produk?.kode ?? '',
      nama_produk: d.produk_nama ?? d.product_name ?? d.produk?.nama ?? '',
      product_image_url: d.product_image_url ?? d.foto_url ?? d.image_url ?? d.produk?.product_image_url ?? d.produk?.foto_url ?? null,
      product_image_thumbnail_url: d.product_image_thumbnail_url ?? d.foto_thumbnail_url ?? d.thumbnail_url ?? d.produk?.product_image_thumbnail_url ?? d.produk?.foto_thumbnail_url ?? null,
      product_image_medium_url: d.product_image_medium_url ?? d.foto_medium_url ?? d.medium_url ?? d.produk?.product_image_medium_url ?? d.produk?.foto_medium_url ?? null,
      satuan: d.satuan_label ?? d.unit_label ?? '',
      qty_beli: Number(d.pos_transaction_item?.quantity ?? d.qty_beli ?? d.posItem?.quantity ?? d.qty_retur ?? 0),
      qty_retur: Number(d.qty_retur ?? 0),
      unit_factor: Number(d.unit_factor ?? d.pos_transaction_item?.unit_factor ?? 1),
      harga_satuan: Number(d.harga_satuan ?? d.unit_price ?? 0),
      subtotal: Number(d.subtotal ?? 0),
    })),
    total_retur: Number(item.total_retur ?? item.jumlah_pengembalian ?? 0),
    payment_detail: item.payment_detail ?? null,
    media_lampiran: (() => {
      // Prioritas: field media_lampiran (flat array URL dari backend baru)
      if (Array.isArray(item.media_lampiran) && item.media_lampiran.length > 0) return item.media_lampiran;
      if (item.media_lampiran && !Array.isArray(item.media_lampiran)) return [item.media_lampiran];
      // Fallback: relasi media (array object dengan field file_url)
      if (Array.isArray(item.media) && item.media.length > 0) {
        return item.media.map((m: any) => m.file_url ?? m.url).filter(Boolean);
      }
      return null;
    })(),
  };
}

