export async function fetchFakturByPelanggan(pelangganId: number, cabangId?: number | null, q?: string): Promise<FakturPenjualan[]> {
  try {
    const res = await apiGet<{ data: any[] }>('mobile/retur-penjualan/invoices', {
      params: { customer_id: pelangganId, cabang_id: cabangId || undefined, q: q || undefined, limit: 50 },
    });
    return (res.data ?? []).map(mapApiFaktur);
  } catch {}

  logMock(`fetchFakturByPelanggan(${pelangganId})`);
  await delay();
  return MOCK_FAKTUR.filter(f => f.pelanggan_id === pelangganId);
}

function mapApiFakturItem(item: any): FakturPenjualanItem {
  const netUnitPrice = Number(item.net_unit_price ?? item.unit_price ?? item.harga_satuan ?? 0);
  const qty = Number(item.qty_available_retur ?? item.quantity ?? item.qty ?? 0);
  const unitPrice = Number(item.unit_price ?? netUnitPrice);
  const discountAmount = Number(item.discount_amount ?? item.discount_rp ?? 0);
  const discountValue = Number(item.discount_value ?? 0);
  const discountMode = item.discount_mode ?? null;
  const unitFactor = Number(item.unit_factor ?? 1);
  return {
