export async function fetchReturPenjualanList(params?: {
  search?: string;
  status?: string;
  date_from?: string;
  date_to?: string;
  cabang_id?: number;
}): Promise<ReturPenjualanItem[]> {
  try {
    const res = await apiGet<any>('mobile/retur-penjualan', { params: { per_page: 100, ...params } });
    const rows = res.data?.data ?? res.data ?? [];
    const mapped = rows.map(mapApiRetur);
    if (!params || Object.keys(params).length === 0) {
      await cacheSet(CACHE_LIST, mapped);
    }
    return mapped;
  } catch {}

  const cached = await cacheGet<ReturPenjualanItem[]>(CACHE_LIST);
  if (cached?.length) return cached;

  logMock('fetchReturPenjualanList fallback');
  await delay();
  return [...MOCK_RETUR].sort((a, b) => (a.created_at < b.created_at ? 1 : -1));
}

export async function fetchReturPenjualanDetail(id: number): Promise<ReturPenjualanItem | null> {
  if (id > 0) {
    try {
      const res = await apiGet<{ data: any }>(`mobile/retur-penjualan/${id}`);
      return mapApiRetur(res.data);
    } catch {}
  }

  logMock(`fetchReturPenjualanDetail(${id}) fallback`);
  await delay();
  return MOCK_RETUR.find(r => r.id === id) ?? null;
}

