import axios, {
  AxiosError,
  AxiosInstance,
  AxiosRequestConfig,
  AxiosResponse,
  InternalAxiosRequestConfig,
} from 'axios';
import { store } from '../app/store';
import { logout } from '../app/slices/authSlice';
import { setOnline } from '../app/slices/syncSlice';
import { refreshAuthToken } from './authRefresh';
import { API_CONFIG } from './config';

function getRetryDelay(attempt: number): number {
  const delay = Math.min(
    API_CONFIG.retry.baseDelay * 2 ** attempt,
    API_CONFIG.retry.maxDelay,
  );
  return delay + Math.random() * 500;
}

function shouldRetry(error: AxiosError, attempt: number): boolean {
  if (attempt >= API_CONFIG.retry.maxRetries) {
    return false;
  }
  if (error.code === 'ECONNABORTED') {
    return true;
  }
  if (!error.response) {
    return true;
  }
  if (
    error.response.status >= 500 ||
    error.response.status === 429
  ) {
    return true;
  }
  return false;
}

const client: AxiosInstance = axios.create({
  baseURL: API_CONFIG.baseUrl,
  timeout: API_CONFIG.timeout,
  headers: {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  },
});

